def get_plan(objects, init, goal):
    objects = list(objects)
    init = set(init)
    goal = set(goal)

    men = [n for n, t in objects if t == "man"]
    if not men:
        return []
    man = men[0]

    spanners = sorted(n for n, t in objects if t == "spanner")
    nuts = sorted(n for n, t in objects if t == "nut")

    links = set()
    for fact in init:
        if fact[0] == "link":
            links.add((fact[1], fact[2]))

    # Initial state encoding.
    spanner_locs = {}
    spanner_usable = {}
    nut_locs = {}
    nut_loose = {}
    man_loc = None
    for fact in init:
        if fact[0] == "at":
            _, who, loc = fact
            if who == man:
                man_loc = loc
            elif who in spanners:
                spanner_locs[who] = loc
            elif who in nuts:
                nut_locs[who] = loc
        elif fact[0] == "useable":
            spanner_usable[fact[1]] = True
        elif fact[0] == "loose":
            nut_loose[fact[1]] = True

    if man_loc is None:
        return []

